CREATE TABLE payment_intents (id VARCHAR(13) PRIMARY KEY,booking_id VARCHAR(36) NOT NULL UNIQUE REFERENCES bookings(id),state VARCHAR(16) NOT NULL,amount DECIMAL(18,0) NOT NULL,bank_code VARCHAR(20) NOT NULL,bank_account VARCHAR(64) NOT NULL,account_name NVARCHAR(150) NOT NULL,content NVARCHAR(500) NOT NULL,qr_code NVARCHAR(4000),qr_link NVARCHAR(2000),transaction_ref_id VARCHAR(512),virtual_account VARCHAR(64),created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,attempt_id VARCHAR(36),attempt_started_at TIMESTAMP(6) WITH TIME ZONE,last_error NVARCHAR(300));
CREATE TABLE payment_receipts (id VARCHAR(36) PRIMARY KEY,transaction_id VARCHAR(128) NOT NULL UNIQUE,receipt_key VARCHAR(64) NOT NULL UNIQUE,reference_number VARCHAR(128) NOT NULL,provider_order_id VARCHAR(64) NOT NULL,booking_id VARCHAR(36) REFERENCES bookings(id),bank_account VARCHAR(64) NOT NULL,amount DECIMAL(18,0) NOT NULL,trans_type VARCHAR(1) NOT NULL,content NVARCHAR(2000) NOT NULL,transaction_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,received_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,state VARCHAR(16) NOT NULL,reason VARCHAR(64));
CREATE INDEX ix_receipts_review ON payment_receipts(state,received_at);
CREATE TABLE payment_callback_lock (id INT PRIMARY KEY);
INSERT INTO payment_callback_lock(id) VALUES(1);
ALTER TABLE bookings ALTER COLUMN payment_reference VARCHAR(128) NULL;
